mapper.select:
select cast(first_time as date) as `day`,count(*) newUsers from (
select o.user_id,min(o.order_time) first_time from orders o where  and o.order_time<#{until} group by o.user_id
) cohort group by 1

select o.id,o.number,o.store_id storeId,o.fulfillment_type fulfillmentType,cast(o.order_time as char(19)) as `day`,'ORDER' event,o.amount from orders o where  and o.order_time>=#{from} and o.order_time<#{until}
union all select o.id,o.number,o.store_id,o.fulfillment_type,cast(o.checkout_time as char(19)),'PAYMENT',o.amount from orders o where  and o.checkout_time>=#{from} and o.checkout_time<#{until}
union all select o.id,o.number,o.store_id,o.fulfillment_type,cast(r.updated_at as char(19)),'REFUND',r.amount_fen/100.0 from orders o join refund_request r on r.order_id=o.id where  and r.status='SUCCESS' and r.updated_at>=#{from} and r.updated_at<#{until}
union all select o.id,o.number,o.store_id,o.fulfillment_type,cast(o.delivery_time as char(19)),'COMPLETED',o.amount from orders o where  and o.status=5 and o.delivery_time>=#{from} and o.delivery_time<#{until}
union all select o.id,o.number,o.store_id,o.fulfillment_type,cast(o.cancel_time as char(19)),'CANCELLED',o.amount from orders o where  and o.status=6 and o.cancel_time>=#{from} and o.cancel_time<#{until}
order by id,event limit 50001
